<?php namespace App\Features\Stock\Livewire;use Livewire\Component;use Livewire\WithPagination;use Livewire\WithFileUploads;use App\Features\Stock\Models\Stock;use App\Features\Stock\Services\StockService;use App\Features\Stock\Enums\StockStatus;
class StockList extends Component{use WithPagination,WithFileUploads;public string $search='';public string $filterStatus='';public bool $showForm=false;public ?int $editingId=null;public string $name='';public string $sku='';public string $description='';public int $quantity=0;public string $unit='pcs';public $price=null;public int $min_stock=5;public $cover;protected $queryString=['search','filterStatus'];public function updatedSearch(){ $this->resetPage();}public function create(){ $this->resetForm();$this->showForm=true;}public function edit(Stock $stock){$this->authorize('update',$stock);$this->editingId=$stock->id;foreach(['name','sku','description','quantity','unit','price','min_stock'] as $f)$this->$f=$stock->$f;$this->showForm=true;}public function save(StockService $service){$data=$this->validate(['name'=>'required|string|max:150','sku'=>'nullable|string|max:60|unique:stocks,sku,'.($this->editingId??'NULL'),'description'=>'nullable|string','quantity'=>'required|integer|min:0','unit'=>'required|string|max:20','price'=>'nullable|numeric|min:0','min_stock'=>'required|integer|min:0','cover'=>'nullable|image|max:2048']);if($this->cover)$data['cover_image_path']=$this->cover->store('stocks','public');unset($data['cover']);if($this->editingId)$service->update(Stock::findOrFail($this->editingId),$data);else $service->create(auth()->id(),$data);$this->showForm=false;$this->resetForm();session()->flash('success','Data stok berhasil disimpan.');}public function adjust(Stock $stock,int $amount,StockService $service){$this->authorize('update',$stock);$service->adjust($stock,$amount);}public function delete(Stock $stock,StockService $service){$this->authorize('delete',$stock);$service->delete($stock);}private function resetForm(){foreach(['name','sku','description','quantity','unit','price','min_stock','cover','editingId'] as $f)$this->$f=match($f){'quantity'=>0,'unit'=>'pcs','min_stock'=>5,default=>null};$this->name='';$this->showForm=false;}public function render(){return view('livewire.stock.stock-list',['stocks'=>Stock::where('user_id',auth()->id())->when($this->search,fn($q)=>$q->where('name','like','%'.$this->search.'%'))->when($this->filterStatus,fn($q)=>$q->where('status',$this->filterStatus))->latest()->paginate(10),'statuses'=>StockStatus::cases()])->layout('components.layouts.app');}}
